def ledger(uid, c, lo, hi, title, ps, inks, crowns):
    verses = list(range(lo, hi + 1))
    sif_cites = [f'Sifrei Bamidbar {p}:{r}' for p in ps for r in range(1, SIF_ROWS[p] + 1)]
    cites = [f'Onkelos Num {c}:{v}' for v in verses] + sif_cites
    N = len(cites); NS = len(sif_cites)
    cnt = Counter(R[(c, v)][0] for v in verses); scnt = Counter(S[(p, r)][0] for p in ps for r in range(1, SIF_ROWS[p] + 1))
    if ps:
        sif_decl = f' + the Sifrei on Numbers piskaot {ps[0]}-{ps[-1]} BY POSITION ({NS} rows at the shelf\'s row grain; every head asserted between its neighbors, none mistyped; the export\'s translator stops inside 121 — the shelf\'s gap recorded)'
    else:
        sif_decl = ' + the Sifrei on Numbers: NO PISKA on this chapter (computed on every head of the export — the shelf\'s silence on Korach as on the spies; the chapter read on the translation alone, the Sifrei\'s next row on 18:1)'
    hdr = (f'# Numbers {c}:{lo}-{hi} derivation — Onkelos + the Sifrei on Numbers as the spine (its piskaot found BY POSITION), '
           f'THE NUMBERS WALK sitting 5 — KORACH, {title} ({DATE}; the owner: "Go" after the #124 rereads, on the ruling NUMBERS IN ORDER FROM 1:1 and READ THEN COMPILE). '
           f'DECLARED (THE_STEPS Step 2, the spine default of 2026-08-27, read at the PARASHAH GRAIN — speed ruling (a): one pass over Korach 16:1-18:32, the three ledgers per block): scope = Onkelos Numbers {c}:{lo}-{hi} ({len(verses)} verses, fresh)'
           + sif_decl + f'. {TESTING[uid]} OUTSIDE DECLARED SCOPE, enumerated and unread (the shelf\'s other works on Numbers, {len(outside)} directories): {", ".join(outside)}.\n\n')
    if ps:
        body = f'## Sifrei Bamidbar piskaot {ps[0]}-{ps[-1]} ({NS} rows, read whole — the heads by position: {"; ".join(f"{p} on {head(p)[0]}:{head(p)[1]}" for p in ps)})\n'
        for p in ps:
            for r in range(1, SIF_ROWS[p] + 1):
                verdict, prose = S[(p, r)]
                body += f'- Sifrei Bamidbar {p}:{r} — {verdict}. {prose}\n'
    else:
        body = f'## Sifrei Bamidbar on chapter {c}: no piska (computed — the export\'s heads run from 115 on 15:37 to 116 on 18:1)\n'
    body += f'\n## Onkelos Numbers {c}:{lo}-{hi} ({len(verses)} verses, read whole)\n'
    for v in verses:
        verdict, prose = R[(c, v)]
        body += f'- Onkelos Num {c}:{v} — {verdict}. {prose}\n'
    body += '\n## The ink beside the shelf (computed by this script from the Tanakh DB, the snapshot store and the shelf — never recited)\n'
    for k in inks: body += INK[k] + '\n'
    body += register_line(c, lo, hi) + '\n'
    body += '\n## The finds (this ledger\'s crowns)\n' + '\n'.join(crowns) + '\n'
    body += (f'\n## CITE INDEX — every source opened, each fully named\n(one name per line; coverage COMPUTED against the shelf by the ledger script write_korach_ledgers.py: Onkelos Numbers {c}:{lo}-{hi} {len(verses)} verses — missing 0, extra 0'
             + (f'; the Sifrei on Numbers piskaot {ps[0]}-{ps[-1]}, {NS} rows at the shelf\'s own row counts — missing 0, extra 0' if ps else '; the Sifrei on Numbers 0 rows on this chapter — computed') + ')\n')
    body += '\n'.join(cites) + '\n'
    body += f'({len(verses)} Onkelos verses fresh' + (f' + {NS} Sifrei Bamidbar rows fresh' if ps else '') + f' = {N} sources in this ledger.)\n\n'
    body += (f'**read: {N} of {N} — COMPLETE** ({len(verses)} Onkelos verses' + (f' and {NS} Sifrei rows' if ps else '') + ' opened and verdicted this sitting at the shelf\'s row grain, coverage computed by script — missing 0, extra 0; '
             f'verdicts MATERIAL {cnt["MATERIAL"]} Onkelos, CONTEXT {cnt["CONTEXT"]} Onkelos' + (f', MATERIAL {scnt["MATERIAL"]} Sifrei, CONTEXT {scnt["CONTEXT"]} Sifrei' if ps else '') + ' — the counts the script\'s own Counter measured)\n')
    open(OUT[uid], 'w', encoding='utf-8').write(hdr + body)
    print(f'wrote {OUT[uid]}: {N} sources, Onkelos MATERIAL {cnt["MATERIAL"]} / CONTEXT {cnt["CONTEXT"]}; Sifrei {NS} rows MATERIAL {scnt["MATERIAL"]} / CONTEXT {scnt["CONTEXT"]}')
    return N, cnt, scnt

